using DrawVerify.Core.Interfaces;
using DrawVerify.Core.Models;
using Microsoft.Data.Sqlite;

namespace DrawVerify.Infrastructure.Persistence;

public sealed class SqliteAuthenticationAuditRepository : IAuthenticationAuditRepository
{
    private readonly string _connectionString;
    public SqliteAuthenticationAuditRepository(string databasePath, ICentralizedLogger? logger = null) { _connectionString = new SqliteConnectionStringBuilder { DataSource = databasePath }.ToString(); try { using var c=new SqliteConnection(_connectionString); c.Open(); using var q=c.CreateCommand(); q.CommandText="CREATE TABLE IF NOT EXISTS AuthenticationAuditLog (AuditId TEXT PRIMARY KEY, ActorUsername TEXT NULL, Username TEXT NOT NULL, TimestampUtc TEXT NOT NULL, Action TEXT NOT NULL, Result TEXT NOT NULL, FailureReason TEXT NULL)"; q.ExecuteNonQuery(); } catch(Exception ex) { logger?.Log(ex,"SQLite authentication audit startup","Unable to initialize authentication audit schema"); throw; } }
    public async Task WriteAsync(AuthenticationAuditEntry entry, CancellationToken cancellationToken = default) { await using var c=new SqliteConnection(_connectionString); await c.OpenAsync(cancellationToken); await using var q=c.CreateCommand(); q.CommandText="INSERT INTO AuthenticationAuditLog (AuditId,ActorUsername,Username,TimestampUtc,Action,Result,FailureReason) VALUES ($id,$actor,$u,$t,$a,$r,$f)"; q.Parameters.AddWithValue("$id",Guid.NewGuid().ToString()); q.Parameters.AddWithValue("$actor",(object?)entry.ActorUsername??DBNull.Value); q.Parameters.AddWithValue("$u",entry.Username); q.Parameters.AddWithValue("$t",entry.TimestampUtc.ToUniversalTime().ToString("O")); q.Parameters.AddWithValue("$a",entry.Action); q.Parameters.AddWithValue("$r",entry.Result); q.Parameters.AddWithValue("$f",(object?)entry.FailureReason??DBNull.Value); await q.ExecuteNonQueryAsync(cancellationToken); }
    internal static async Task InsertAsync(SqliteConnection c, SqliteTransaction tx, AuthenticationAuditEntry entry, CancellationToken token) { await using var q=c.CreateCommand(); q.Transaction=tx; q.CommandText="INSERT INTO AuthenticationAuditLog (AuditId,ActorUsername,Username,TimestampUtc,Action,Result,FailureReason) VALUES ($id,$actor,$u,$t,$a,$r,$f)"; q.Parameters.AddWithValue("$id",Guid.NewGuid().ToString()); q.Parameters.AddWithValue("$actor",(object?)entry.ActorUsername??DBNull.Value); q.Parameters.AddWithValue("$u",entry.Username); q.Parameters.AddWithValue("$t",entry.TimestampUtc.ToUniversalTime().ToString("O")); q.Parameters.AddWithValue("$a",entry.Action); q.Parameters.AddWithValue("$r",entry.Result); q.Parameters.AddWithValue("$f",(object?)entry.FailureReason??DBNull.Value); await q.ExecuteNonQueryAsync(token); }
}
